import secrets
import string


class ShortCodeGenerator:
    """Generate unique short codes for the lifetime of this process."""

    def __init__(self, length: int = 7) -> None:
        if not 6 <= length <= 8:
            raise ValueError("Short-code length must be between 6 and 8 characters")
        self.length = length
        self._alphabet = string.ascii_letters + string.digits
        self._used_codes: set[str] = set()

    def generate(self) -> str:
        """Return a URL-friendly code not previously generated by this instance."""
        while True:
            code = "".join(
                secrets.choice(self._alphabet) for _ in range(self.length)
            )
            if code not in self._used_codes:
                self._used_codes.add(code)
                return code


short_code_generator = ShortCodeGenerator()
